exercises.starter_code:
#include <stdio.h>

int main(void) {
    int arr[5] = {1, 2, 3, 4, 5};
    // print [1 2 3 4 5]
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    int arr[5] = {1, 2, 3, 4, 5};
    printf("[");
    for (int i = 0; i < 5; i++) {
        if (i) putchar(' ');
        printf("%d", arr[i]);
    }
    puts("]");
    return 0;
}

