exercises.starter_code:
#include <stdio.h>

int main(void) {
    int matrix[2][2] = {{1, 2}, {3, 4}};
    // print each element
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    int matrix[2][2] = {{1, 2}, {3, 4}};
    for (int r = 0; r < 2; r++)
        for (int c = 0; c < 2; c++)
            printf("%d\n", matrix[r][c]);
    return 0;
}

exercises.starter_code:
#include <stdio.h>

int main(void) {
    int arr[] = {10, 20, 30, 40, 50};
    // sum and print
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <stddef.h>

int main(void) {
    int arr[] = {10, 20, 30, 40, 50};
    int sum = 0;
    for (size_t i = 0; i < 5; i++) sum += arr[i];
    printf("%d\n", sum);
    return 0;
}

